      <ul class="almanac-gate-list">${(c()?[["37 s \u2192 4.2 ms","\u4ECE\u672A\u88AB\u300C\u5148\u6682\u7F13\u300D\uFF0C\u662F\u538B\u51FA\u6765\u7684\u2014\u2014T982 \u771F\u5B9E\u538B\u6D4B\uFF0C\u8BB0\u5F55\u5728\u6848"],["2490 \xD7 0","c=50\u300120 \u79D2\u3001\u96F6\u9519\u8BEF\uFF1BLOAD_TESTING.md \u539F\u6587"],["2 \u5B57\u8282\u7684\u6C89\u9ED8","\u8BA9 ledger \u5BF9 grep \u9690\u5F62\uFF1B\u95E8\u7ACB\u8D77\u6765\u4E86\uFF0C\u9884\u7B97\u4E0D\u8BB8\u6DA8"],["3 \u5468\u7684\u7A7A\u767D","push cancel \u6389 push\uFF1B\u95E8\u8BA9\u5B83\u518D\u4E5F\u85CF\u4E0D\u4F4F"],["\u95E8\u4ECE\u4E0D\u62AC","\u5BF9\u6BD4\u5EA6\u95E8\u3001focus \u95E8\u3001NUL \u95E8\u3001wait-claim \u95E8\u2014\u2014\u7EA2\u4E00\u5F8B\u7531\u4FEE\u4EE3\u7801\u6EE1\u8DB3"]]:[["37 s \u2192 4.2 ms","never paused, only pressed \u2014 T982 measurement, on the record"],["2,490 \xD7 0","c=50, 20 seconds, zero errors; verbatim from LOAD_TESTING.md"],["Two silent bytes","the ledger went invisible to grep; the gate stands, the budget stays at 2"],["Three quiet weeks","pushes cancelled pushes; the gate makes that impossible to hide again"],["The floor never moved","contrast, focus, NUL, wait-claim \u2014 every red was fixed forward, never by raising a budget"]]).map(([t,a])=>`<li><strong>${o(t)}</strong><span>${o(a)}</span></li>`).join("")}</ul>
